function updateSyncStatus(status) {
 syncStatus=status;const el=$('#database-status');if(!el)return;
 const labels={saved:'Сохранено в базе',syncing:'Сохраняем в базу…',offline:'В браузере · база недоступна',conflict:'Нужно сверить версии'};
 el.textContent=labels[status.kind]||status.message;el.className=`database-status ${status.kind}`;el.title=status.updatedAt?`Последняя запись: ${new Date(status.updatedAt).toLocaleString('ru-RU')}`:(status.message||'');
 const conflict=$('#sync-conflict');if(conflict)conflict.hidden=status.kind!=='conflict';
}
