function save(message='Сохранено на этом устройстве') {
  if(corruptRaw) { toast('Сначала восстановите данные из файла. Исходное сохранение защищено.'); return false; }
  let candidate;
  try { candidate=validateImport(state); } catch(e) { state=JSON.parse(validSnapshot); toast(`Изменение не применено: ${e.message}`); return false; }
  state=candidate;validSnapshot=JSON.stringify(state);
  try { localStorage.setItem(STORAGE_KEY,validSnapshot); storageIssue='';sync?.queue(state);if(submittingForm)formDrafts.delete(submittingForm.dataset.draftKey); toast(message); return true; }
  catch(e) { storageIssue=`Не удалось записать данные в браузер. Экспортируйте их, прежде чем закрывать приложение.`; toast(storageIssue); return false; }
}
