function restoreFormDrafts() {
 for(const form of document.querySelectorAll('#app form')){
  const id=form.id||form.dataset.answerKey;if(!id)continue;
  const key=id+':'+(form.elements.entryDate?.value||form.elements.month?.value||dateKey());form.dataset.draftKey=key;
  const draft=formDrafts.get(key);if(!draft)continue;
  for(const [name,value] of Object.entries(draft)){const field=form.elements.namedItem(name);if(field&&'value' in field)field.value=value;}
  let parent=form.parentElement;while(parent){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}
  formDirty=true;
 }
}
function keepFormDraft(target) {
 const form=target.closest('form');if(!form?.dataset.draftKey||target.dataset.answer||target.name==='entryDate')return;
 formDrafts.set(form.dataset.draftKey,Object.fromEntries(new FormData(form)));formDirty=true;
}
